const config = {
    "previewFeatures": [],
    "clientVersion": "7.9.1",
    "engineVersion": "e922089b7d7502aff4249d5da3420f6fa55fc6ad",
    "activeProvider": "postgresql",
    "inlineSchema": "// Raven control plane schema.\n// See docs/architecture/infrastructure-decisions.md for why Prisma/Postgres.\n// See docs/control-plane.md for the full data-model rationale.\n\ngenerator client {\n  provider     = \"prisma-client\"\n  output       = \"../src/generated/prisma\"\n  moduleFormat = \"cjs\"\n  runtime      = \"nodejs\"\n}\n\n// Prisma 7 dropped `url` here — it lives in prisma.config.ts for the CLI now,\n// and PrismaClient gets it via the driver adapter (prisma.service.ts).\n// https://pris.ly/d/config-datasource\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum ProjectStatus {\n  ACTIVE\n  ARCHIVED\n}\n\nenum ApiKeyStatus {\n  ACTIVE\n  REVOKED\n}\n\nenum RoomStatus {\n  ACTIVE\n  CLOSED\n}\n\nenum ParticipantStatus {\n  PENDING\n  JOINED\n  LEFT\n}\n\nenum ConnectionState {\n  CONNECTING\n  CONNECTED\n  RECONNECTING\n  DISCONNECTED\n  FAILED\n}\n\n/// Raven-facing error categories (Phase 9 spec §18) — never the raw\n/// LiveKit/coturn error a developer would have to reverse-engineer.\nenum ErrorCategory {\n  AUTHENTICATION_ERROR\n  AUTHORIZATION_ERROR\n  TOKEN_ERROR\n  SIGNALING_ERROR\n  ICE_ERROR\n  TURN_ERROR\n  SFU_ERROR\n  NETWORK_ERROR\n  CLIENT_ERROR\n  UNKNOWN_ERROR\n}\n\nmodel User {\n  id           String   @id @default(uuid())\n  email        String   @unique\n  passwordHash String\n  name         String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  projects Project[]\n\n  @@map(\"users\")\n}\n\nmodel Project {\n  id          String        @id @default(uuid())\n  name        String\n  description String?\n  status      ProjectStatus @default(ACTIVE)\n  ownerId     String\n  owner       User          @relation(fields: [ownerId], references: [id], onDelete: Restrict)\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n\n  apiKeys     ApiKey[]\n  rooms       Room[]\n  connections Connection[]\n  errorEvents ErrorEvent[]\n\n  conversations    Conversation[]\n  chatConnections  ChatConnection[]\n  webhookEndpoints WebhookEndpoint[]\n\n  @@index([ownerId])\n  @@map(\"projects\")\n}\n\n/// The raw secret is never stored — only a hash of it. `publicId` is the\n/// fast, non-secret lookup key used to find the row before verifying the\n/// secret against `secretHash`. See docs/control-plane.md#api-keys.\nmodel ApiKey {\n  id         String       @id @default(uuid())\n  projectId  String\n  project    Project      @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  publicId   String       @unique\n  secretHash String\n  name       String?\n  status     ApiKeyStatus @default(ACTIVE)\n  lastUsedAt DateTime?\n  createdAt  DateTime     @default(now())\n  revokedAt  DateTime?\n\n  @@index([projectId])\n  @@map(\"api_keys\")\n}\n\nmodel Room {\n  id        String     @id @default(uuid())\n  projectId String\n  project   Project    @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  name      String\n  status    RoomStatus @default(ACTIVE)\n  createdAt DateTime   @default(now())\n  updatedAt DateTime   @updatedAt\n\n  participants Participant[]\n  rtcTokens    RtcToken[]\n  /// The chat channel attached to this RTC room, if one was created.\n  /// Chat and RTC stay separate services — this is the only join between them.\n  conversation Conversation?\n\n  // Room names only need to be unique within a project, so unrelated\n  // projects can independently use the same room name (e.g. \"lobby\").\n  @@unique([projectId, name])\n  @@index([projectId])\n  @@map(\"rooms\")\n}\n\n/// A logical identity within a room's control-plane record. Real join/leave\n/// state (from LiveKit webhooks) is wired up in a later phase; for now this\n/// row exists so RTC tokens have something durable to reference and so a\n/// consistent identity is enforced per room.\nmodel Participant {\n  id        String            @id @default(uuid())\n  roomId    String\n  room      Room              @relation(fields: [roomId], references: [id], onDelete: Cascade)\n  identity  String\n  status    ParticipantStatus @default(PENDING)\n  metadata  Json?\n  createdAt DateTime          @default(now())\n  updatedAt DateTime          @updatedAt\n\n  rtcTokens RtcToken[]\n\n  @@unique([roomId, identity])\n  @@map(\"participants\")\n}\n\n/// A control-plane record of a granted RTC token. The actual bearer\n/// credential is a signed LiveKit JWT returned once at creation time and\n/// never persisted — this row is the audit/metadata trail, not the secret\n/// itself. See docs/control-plane.md#rtc-tokens.\nmodel RtcToken {\n  id            String      @id @default(uuid())\n  projectId     String\n  roomId        String\n  room          Room        @relation(fields: [roomId], references: [id], onDelete: Cascade)\n  participantId String\n  participant   Participant @relation(fields: [participantId], references: [id], onDelete: Cascade)\n  permissions   Json\n  expiresAt     DateTime\n  createdAt     DateTime    @default(now())\n\n  @@index([projectId])\n  @@index([roomId])\n  @@map(\"rtc_tokens\")\n}\n\n/// A real RTC connection, event-sourced from best-effort SDK telemetry\n/// (Phase 9) — distinct from `RtcToken` (a grant) and from LiveKit's own\n/// internal session bookkeeping. `publicId` (`conn_...`) is generated\n/// client-side by `@raven/rtc` at `join()` time and is the ID surfaced in\n/// the dashboard, the CLI, and any error report, so a developer can\n/// correlate all three without ever touching LiveKit/coturn directly. See\n/// docs/observability.md#connection-lifecycle.\nmodel Connection {\n  id                  String          @id @default(uuid())\n  publicId            String          @unique\n  projectId           String\n  project             Project         @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  roomId              String?\n  roomName            String\n  participantId       String?\n  participantIdentity String\n  state               ConnectionState @default(CONNECTING)\n  disconnectReason    String?\n  region              String?\n  sdkVersion          String?\n  platform            String?\n  browser             String?\n  networkType         String?\n  iceConnectionState  String?\n  signalingState      String?\n  reconnectCount      Int             @default(0)\n  startedAt           DateTime        @default(now())\n  connectedAt         DateTime?\n  disconnectedAt      DateTime?\n  durationMs          Int?\n  createdAt           DateTime        @default(now())\n  updatedAt           DateTime        @updatedAt\n\n  events ConnectionEvent[]\n  errors ErrorEvent[]\n\n  @@index([projectId])\n  @@index([roomId])\n  @@index([participantId])\n  @@index([createdAt])\n  @@map(\"connections\")\n}\n\n/// The append-only timeline behind a Connection's detail view (Phase 9\n/// spec §17) — every lifecycle transition and metadata update, never\n/// mutated after being written.\nmodel ConnectionEvent {\n  id           String     @id @default(uuid())\n  connectionId String\n  connection   Connection @relation(fields: [connectionId], references: [id], onDelete: Cascade)\n  type         String\n  data         Json?\n  timestamp    DateTime   @default(now())\n\n  @@index([connectionId])\n  @@index([timestamp])\n  @@map(\"connection_events\")\n}\n\n/// A classified, developer-facing error (Phase 9 spec §18-20). `category`\n/// is always a Raven concept (never a raw LiveKit/coturn error code) —\n/// see `error-classifier.ts` for the mapping and docs/error-codes.md for\n/// the full reference.\nmodel ErrorEvent {\n  id              String        @id @default(uuid())\n  publicId        String        @unique\n  projectId       String\n  project         Project       @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  connectionId    String?\n  connection      Connection?   @relation(fields: [connectionId], references: [id], onDelete: SetNull)\n  roomId          String?\n  participantId   String?\n  category        ErrorCategory\n  message         String\n  likelyCause     String?\n  suggestedAction String?\n  sdkVersion      String?\n  platform        String?\n  timestamp       DateTime      @default(now())\n\n  @@index([projectId])\n  @@index([connectionId])\n  @@index([category])\n  @@index([timestamp])\n  @@map(\"error_events\")\n}\n\n// ---------------------------------------------------------------------------\n// Chat (Phase 12)\n//\n// Postgres is the source of truth for everything durable below. Presence,\n// typing, and WebSocket connection routing are deliberately absent here —\n// they live in Redis with TTLs (see docs/chat/architecture.md#redis), because\n// writing an `online`/`offline` transition to Postgres on every tab focus is\n// exactly the kind of cost this design is trying to avoid.\n// ---------------------------------------------------------------------------\n\nenum ConversationType {\n  /// Backed by an RTC `Room` — the chat side of a video call.\n  ROOM\n  /// Standalone, long-lived channel with no RTC room attached.\n  CHANNEL\n  /// Two-party conversation. Same model, just a different membership shape.\n  DIRECT\n}\n\nenum ConversationStatus {\n  ACTIVE\n  ARCHIVED\n}\n\n/// Coarse roles that expand into the `chat:*` scopes in\n/// chat-permissions.ts. Deliberately not a general RBAC system (Phase 12\n/// spec §28) — but roles are stored, not scopes, so the mapping can grow\n/// without a migration.\nenum ChatMemberRole {\n  MEMBER\n  MODERATOR\n  ADMIN\n}\n\nenum ChatMemberStatus {\n  ACTIVE\n  LEFT\n}\n\nenum MessageType {\n  TEXT\n  SYSTEM\n  EVENT\n  ATTACHMENT\n}\n\nenum AttachmentStatus {\n  /// Upload URL handed out, bytes not confirmed in object storage yet.\n  PENDING\n  UPLOADED\n  EXPIRED\n}\n\nenum WebhookEndpointStatus {\n  ACTIVE\n  DISABLED\n}\n\nenum WebhookDeliveryStatus {\n  PENDING\n  DELIVERED\n  FAILED\n}\n\n/// A chat channel. `publicId` (`conv_...`) is what the SDK and dashboard\n/// show; the uuid `id` never leaves the API. A conversation may be pinned\n/// to an RTC `Room` (type ROOM), which is how a video call gets a chat\n/// panel without the developer wiring two identities together.\nmodel Conversation {\n  id            String             @id @default(uuid())\n  publicId      String             @unique\n  projectId     String\n  project       Project            @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  /// Set only for type ROOM. One conversation per room, enforced below.\n  roomId        String?            @unique\n  room          Room?              @relation(fields: [roomId], references: [id], onDelete: Cascade)\n  name          String\n  type          ConversationType   @default(CHANNEL)\n  status        ConversationStatus @default(ACTIVE)\n  /// Overrides the project/plan default. Null = keep messages indefinitely.\n  retentionDays Int?\n  metadata      Json?\n  createdAt     DateTime           @default(now())\n  updatedAt     DateTime           @updatedAt\n\n  members     ChatMember[]\n  messages    Message[]\n  reactions   Reaction[]\n  readStates  ReadState[]\n  attachments Attachment[]\n  connections ChatConnection[]\n\n  // Names are unique per project so `chat.connect({ room: \"support\" })`\n  // can resolve without the developer having to carry a conv_ id around.\n  @@unique([projectId, name])\n  @@index([projectId, createdAt])\n  @@map(\"chat_conversations\")\n}\n\n/// Membership + role for one identity in one conversation. `userId` is the\n/// developer's own user identity string (same concept as an RTC\n/// participant identity) — Raven never owns end-user accounts.\nmodel ChatMember {\n  id             String           @id @default(uuid())\n  conversationId String\n  conversation   Conversation     @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  projectId      String\n  userId         String\n  role           ChatMemberRole   @default(MEMBER)\n  status         ChatMemberStatus @default(ACTIVE)\n  metadata       Json?\n  joinedAt       DateTime         @default(now())\n  leftAt         DateTime?\n\n  @@unique([conversationId, userId])\n  @@index([projectId, userId])\n  @@map(\"chat_members\")\n}\n\n/// The durable message record. Soft-deleted only (`deletedAt`) so a\n/// `message.deleted` event can still name the row and moderation keeps an\n/// audit trail — see docs/chat/messages.md#deletion.\nmodel Message {\n  id               String       @id @default(uuid())\n  publicId         String       @unique\n  projectId        String\n  conversationId   String\n  conversation     Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  /// Denormalized from the conversation so RTC-room-scoped queries and\n  /// webhook payloads don't need a join. Null for CHANNEL/DIRECT.\n  roomId           String?\n  senderId         String\n  type             MessageType  @default(TEXT)\n  /// Null for messages that carry no text (a bare attachment, say).\n  content          String?\n  /// Direct parent. Threads are this same table, not a second store\n  /// (spec §26) — `threadRootId` just makes \"give me the thread\" one\n  /// indexed range scan instead of a recursive walk.\n  replyToMessageId String?\n  replyToMessage   Message?     @relation(\"MessageReplies\", fields: [replyToMessageId], references: [id], onDelete: SetNull)\n  replies          Message[]    @relation(\"MessageReplies\")\n  threadRootId     String?\n  /// Caller-supplied idempotency key. A retry after a reconnect reuses it\n  /// and gets the original message back instead of a duplicate (spec §16).\n  clientMessageId  String?\n  metadata         Json?\n  editedAt         DateTime?\n  deletedAt        DateTime?\n  deletedBy        String?\n  createdAt        DateTime     @default(now())\n  updatedAt        DateTime     @updatedAt\n\n  reactions   Reaction[]\n  readStates  ReadState[]\n  attachments Attachment[]\n\n  // The idempotency guarantee itself. Scoped to sender as well as\n  // conversation so two clients can't collide on a generic key like \"1\".\n  @@unique([conversationId, senderId, clientMessageId], map: \"chat_messages_idempotency_key\")\n  // Covers the only hot read path: newest-first history for one\n  // conversation, keyset-paginated on (createdAt, id).\n  @@index([conversationId, createdAt, id])\n  @@index([senderId, createdAt])\n  @@index([threadRootId, createdAt])\n  @@map(\"chat_messages\")\n}\n\nmodel Reaction {\n  id             String       @id @default(uuid())\n  messageId      String\n  message        Message      @relation(fields: [messageId], references: [id], onDelete: Cascade)\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  projectId      String\n  userId         String\n  emoji          String\n  createdAt      DateTime     @default(now())\n\n  // One user, one emoji, one message — a double-tap is a no-op, not a\n  // second row (spec §23).\n  @@unique([messageId, userId, emoji])\n  @@index([messageId])\n  @@map(\"chat_reactions\")\n}\n\n/// One row per (conversation, user) holding the *latest* read position,\n/// not one row per read event (spec §22). Marking 500 messages read\n/// updates a single row.\nmodel ReadState {\n  id                String       @id @default(uuid())\n  conversationId    String\n  conversation      Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  projectId         String\n  userId            String\n  lastReadMessageId String?\n  lastReadMessage   Message?     @relation(fields: [lastReadMessageId], references: [id], onDelete: SetNull)\n  /// createdAt of the last-read message, copied here so \"unread count\"\n  /// is a single range count with no join back to messages.\n  lastReadAt        DateTime\n  updatedAt         DateTime     @updatedAt\n\n  @@unique([conversationId, userId])\n  @@index([lastReadMessageId])\n  @@map(\"chat_read_states\")\n}\n\n/// Metadata only. The bytes live in S3-compatible object storage and are\n/// only ever reached through short-lived signed URLs (spec §30) — no blob\n/// ever passes through Postgres or the WebSocket.\nmodel Attachment {\n  id             String           @id @default(uuid())\n  publicId       String           @unique\n  projectId      String\n  conversationId String\n  conversation   Conversation     @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  messageId      String?\n  message        Message?         @relation(fields: [messageId], references: [id], onDelete: SetNull)\n  uploaderId     String\n  filename       String\n  mimeType       String\n  sizeBytes      Int\n  storageKey     String           @unique\n  status         AttachmentStatus @default(PENDING)\n  metadata       Json?\n  createdAt      DateTime         @default(now())\n  uploadedAt     DateTime?\n\n  @@index([conversationId])\n  @@index([messageId])\n  @@map(\"chat_attachments\")\n}\n\n/// One WebSocket session against the chat gateway. Deliberately not one\n/// row per presence transition — this is the session, and presence\n/// itself is Redis-only. Mirrors the RTC `Connection` model so the\n/// dashboard's connection views work the same way for both planes.\nmodel ChatConnection {\n  id               String          @id @default(uuid())\n  publicId         String          @unique\n  projectId        String\n  project          Project         @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  conversationId   String?\n  conversation     Conversation?   @relation(fields: [conversationId], references: [id], onDelete: SetNull)\n  userId           String\n  /// Which gateway instance owns the socket — the thing you need when a\n  /// single instance in a fleet starts misbehaving.\n  gatewayId        String\n  state            ConnectionState @default(CONNECTING)\n  disconnectReason String?\n  sdkVersion       String?\n  platform         String?\n  messagesSent     Int             @default(0)\n  connectedAt      DateTime?\n  disconnectedAt   DateTime?\n  durationMs       Int?\n  createdAt        DateTime        @default(now())\n  updatedAt        DateTime        @updatedAt\n\n  @@index([projectId, createdAt])\n  @@index([userId])\n  @@map(\"chat_connections\")\n}\n\n/// A developer-registered webhook target. Project-scoped rather than\n/// chat-scoped on purpose: RTC/recording/streaming events in later phases\n/// deliver through this same pipeline (spec §31 — no second webhook\n/// architecture).\nmodel WebhookEndpoint {\n  id                  String                @id @default(uuid())\n  publicId            String                @unique\n  projectId           String\n  project             Project               @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  url                 String\n  description         String?\n  /// Empty = every event type. Otherwise an allow-list of `message.created`\n  /// style names.\n  enabledEvents       String[]              @default([])\n  /// HMAC-SHA256 signing key. Has to be recoverable to sign each delivery,\n  /// so unlike an API key this is stored as-is and shown once at creation;\n  /// it is never returned again. See docs/chat/webhooks.md#signatures.\n  signingSecret       String\n  status              WebhookEndpointStatus @default(ACTIVE)\n  consecutiveFailures Int                   @default(0)\n  lastDeliveryAt      DateTime?\n  createdAt           DateTime              @default(now())\n  updatedAt           DateTime              @updatedAt\n\n  deliveries WebhookDelivery[]\n\n  @@index([projectId])\n  @@map(\"webhook_endpoints\")\n}\n\n/// The event itself, recorded once regardless of how many endpoints it\n/// fans out to. `publicId` (`evt_...`) is the idempotency key a receiver\n/// should dedupe on (spec §32).\nmodel WebhookEvent {\n  id        String   @id @default(uuid())\n  publicId  String   @unique\n  projectId String\n  type      String\n  payload   Json\n  createdAt DateTime @default(now())\n\n  deliveries WebhookDelivery[]\n\n  @@index([projectId, createdAt])\n  @@map(\"webhook_events\")\n}\n\n/// One (event, endpoint) attempt chain. The worker claims rows by\n/// `status = PENDING AND nextAttemptAt <= now()`, which is what the\n/// composite index below serves.\nmodel WebhookDelivery {\n  id             String                @id @default(uuid())\n  eventId        String\n  event          WebhookEvent          @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  endpointId     String\n  endpoint       WebhookEndpoint       @relation(fields: [endpointId], references: [id], onDelete: Cascade)\n  status         WebhookDeliveryStatus @default(PENDING)\n  attempts       Int                   @default(0)\n  nextAttemptAt  DateTime              @default(now())\n  responseStatus Int?\n  /// Truncated, and never the response body — a failing endpoint can\n  /// echo back anything, including things we shouldn't store.\n  lastError      String?\n  deliveredAt    DateTime?\n  createdAt      DateTime              @default(now())\n  updatedAt      DateTime              @updatedAt\n\n  @@unique([eventId, endpointId])\n  @@index([status, nextAttemptAt])\n  @@index([endpointId, createdAt])\n  @@map(\"webhook_deliveries\")\n}\n",
    "runtimeDataModel": {
        "models": {},
        "enums": {},
        "types": {}
    },
    "parameterizationSchema": {
        "strings": [],
        "graph": ""
    }
};
